  useEffect(()=>()=>{recognition.current?.stop();if('speechSynthesis'in window)window.speechSynthesis.cancel()},[]);
  useEffect(()=>{if(missing&&query&&lastMissing.current!==`${query}`){lastMissing.current=query;setVoiceMessage(NOT_FOUND);if(voiceOn&&'speechSynthesis'in window&&typeof SpeechSynthesisUtterance!=='undefined'){window.speechSynthesis.cancel();window.speechSynthesis.speak(new SpeechSynthesisUtterance(NOT_FOUND));}}},[missing,query,voiceOn]);
