  useEffect(()=>{if(location.state?.speakRestricted){const text='This guide is restricted by the homeowner.';if('speechSynthesis'in window&&typeof SpeechSynthesisUtterance!=='undefined'){window.speechSynthesis.cancel();window.speechSynthesis.speak(new SpeechSynthesisUtterance(text));}}return()=>{if('speechSynthesis'in window)window.speechSynthesis.cancel()}},[location.key]);
